def is_kawaii(sequence):
    N = len(sequence)
    if N == 0:
        return False

    # 1. Find maximum element M
    M = max(sequence)

    # Helper to find first and last index (1-based)
    def get_indices(value):
        indices = [i + 1 for i, x in enumerate(sequence) if x == value]
        if not indices:
            return None, None
        return min(indices), max(indices)

    # 2. Check Condition 2: All numbers 1 to M must appear
    for k in range(1, M + 1):
        if k not in sequence:
            # This should not happen if M=max(sequence), unless M=0 which is impossible here
            return False 

    # 3. Check Condition 3: i_1(k-1) < i_L(k) for k >= 2
    for k in range(2, M + 1):
        i1_km1, _ = get_indices(k - 1)
        _, iL_k = get_indices(k)

        # Since k <= M, both k and k-1 must appear. Indices must be non-None.
        if i1_km1 is None or iL_k is None:
            # Should not happen based on Condition 2 check above
            return False 

        if i1_km1 >= iL_k:
            return False

    return True

